document.addEventListener('input',e=>{const t=e.target;if(!state.active)return;let changed=false;if(t.dataset.set){const n=t.value===''?null:Number(t.value),field=t.dataset.set,set=state.active.exercises[Number(t.dataset.i)]?.sets[Number(t.dataset.j)];if(!set)return;if(field==='rpe'){if(n!==null&&(!Number.isFinite(n)||n<0||n>10))return;set.rpe=n}else{if(n===null||!Number.isFinite(n)||n<0||n>setLimit(field))return;set[field]=field==='weight'?kg(n):['reps','seconds'].includes(field)?Math.floor(n):n}changed=true}if(t.dataset.session){state.active[t.dataset.session]=t.value.slice(0,t.dataset.session==='name'?200:2000);changed=true}if(t.hasAttribute('data-note')){state.active.exercises[Number(t.dataset.i)].notes=t.value.slice(0,2000);changed=true}if(changed)save()});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.set){const n=t.value===''?null:Number(t.value),field=t.dataset.set,s=state.active.exercises[Number(t.dataset.i)].sets[Number(t.dataset.j)];if(field==='rpe'){if(n!==null&&(!Number.isFinite(n)||n<0||n>10)){toast('RPE must be between 0 and 10.');render();return}s.rpe=n}else{if(n===null||!Number.isFinite(n)||n<0||n>setLimit(field)){toast('Enter a valid positive number.');render();return}s[field]=field==='weight'?kg(n):['reps','seconds'].includes(field)?Math.floor(n):n}save()}if(t.dataset.session){state.active[t.dataset.session]=t.value.slice(0,t.dataset.session==='name'?200:2000);save()}if(t.hasAttribute('data-note')){state.active.exercises[Number(t.dataset.i)].notes=t.value.slice(0,2000);save()}if(t.id==='unit'){state.settings.unit=t.value;save();render()}if(t.id==='rest'){state.settings.rest=Math.min(600,Math.max(0,Number(t.value)||0));save();render()}if(t.id==='theme'){state.settings.theme=['warm','charcoal','contrast'].includes(t.value)?t.value:'warm';save();render()}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>450000)throw Error('Backup exceeds the 450 KB limit.');const imported=JSON.parse(await t.files[0].text());if(!valid(imported))throw Error('This is not a valid FORGE v1 backup.');confirmAction('Replace your journal?',`Import ${imported.workouts.length} workouts and ${imported.routines.length} routines? Your current journal will be replaced.`,()=>{state=imported;save();render();toast('Backup imported.')})}catch(err){toast(err.message)}t.value=''}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('online',()=>{if(user)save()});render();queueMicrotask(()=>{if(!state.profile&&!state.workouts.length&&!state.routines.length&&!state.active&&!localStorage.getItem('forge-welcome-seen')&&!localStorage.getItem('forge-setup-skipped'))welcome()});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
(async()=>{const initialMutation=mutationCount;try{const r=await fetch('/api/auth/me');if(!r.ok)return;const d=await r.json(),s=await fetch('/api/state');if(!s.ok)return;const remote=await s.json();if(!valid(remote.state||empty()))return;if(mutationCount!==initialMutation){toast('Sign in through Settings to load your account after these local changes.');return}user=d.user;revision=remote.revision;try{cachedAccount=JSON.parse(localStorage.getItem('forge-account-'+user.id))||cachedAccount}catch{cachedAccount=null}if(cachedAccount&&JSON.stringify(cachedAccount)!==JSON.stringify(remote.state||empty())){state=cachedAccount;syncConflict=true;$('#sync-status').textContent='Unsynced local changes · export then reload';toast('Local and account journals differ. Export your local journal before reloading account data.');render();return}if(localStorage.getItem('forge-mode')!=='account')localStorage.setItem('forge-local-backup',JSON.stringify(state));state=remote.state||empty();localStorage.setItem('forge-mode','local');localStorage.setItem('forge-account-'+user.id,JSON.stringify(state));$('#sync-status').textContent='Account loaded';render()}catch{}})();

function guideButton(e){const item=catalog.find(c=>c.id===e.id),hasInstructions=Array.isArray(item?.instructions)&&item.instructions.length>0,hasCue=typeof (item?.notes||e.notes)==='string'&&Boolean(item?.notes||e.notes);return (demoNames[e.demoKey]?`<button type="button" class="ghost guide-button" data-action="guide" data-id="${e.demoKey}" aria-label="View local movement guide for ${esc(e.name)}">▷ Local guide</button>`:'')+(hasInstructions||hasCue?`<button type="button" class="ghost guide-button" data-action="instructions" data-id="${esc(e.id)}" aria-label="View written steps for ${esc(e.name)}">Steps</button>`:'')}
function showInstructions(id){const exercise=catalog.find(c=>c.id===id);if(!exercise)return;const steps=Array.isArray(exercise.instructions)&&exercise.instructions.length?exercise.instructions:(exercise.notes?[exercise.notes]:[]);if(!steps.length)return;const previous=Array.from($('#modal-content').childNodes),wasOpen=$('#modal').open;modal(esc(exercise.name),`<span class="tag">WRITTEN MOVEMENT GUIDE</span><ol class="guide-cues">${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><p class="help">General exercise information, not personalized coaching. Adjust with a qualified trainer if needed. Stop if a movement causes pain.</p>${wasOpen?'<button type="button" class="ghost section-space" id="instructions-back">Back</button>':''}`);if(wasOpen)$('#instructions-back').onclick=()=>$('#modal-content').replaceChildren(...previous)}
function showGuide(key){if(!demoNames[key])return;const previous=Array.from($('#modal-content').childNodes),wasOpen=$('#modal').open;let paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const cues={squat:['Feet in a comfortable stance; lower only as far as you can control.','Keep your knees tracking with your toes; stand smoothly.'],pushup:['Hands under or slightly outside shoulders; keep your trunk steady.','Lower with control. Use a wall or incline to make this easier.'],row:['Support your torso; keep your spine in a comfortable neutral position.','Pull the elbow toward the hip without twisting; lower slowly.'],hinge:['Soften the knees and send the hips back.','Keep the load close; stop before your back position changes.'],bridge:['Lie on your back with knees bent and feet planted.','Raise the hips smoothly without arching the lower back.'],deadbug:['Lie on your back and brace gently.','Extend opposite arm and leg only as far as you can keep your trunk steady.']};modal(demoNames[key],`<span class="tag">SCHEMATIC MOVEMENT GUIDE</span><img class="movement-demo" id="movement-demo" src="/demos/${key}.${paused?'png':'gif'}" alt="Animated schematic demonstrating the ${esc(demoNames[key])} movement pattern"><button class="secondary" id="guide-toggle">${paused?'Play animation':'Pause animation'}</button><ul class="guide-cues">${cues[key].map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p class="help">An original simplified illustration of a movement pattern; your exercise variant may differ. It cannot assess your individual technique. Start within a comfortable range; stop if you feel pain.</p>${wasOpen?'<button class="ghost section-space" id="guide-back">Back</button>':''}`);$('#guide-toggle').onclick=()=>{paused=!paused;$('#movement-demo').src=`/demos/${key}.${paused?'png':'gif'}`;$('#guide-toggle').textContent=paused?'Play animation':'Pause animation'};if(wasOpen)$('#guide-back').onclick=()=>{$('#modal-content').replaceChildren(...previous)} }
let setupDraft=null,setupStep=0,pickerCallback=null,reviewedSessions=[];
function planCard(s){if(!s.profile)return '';const rec=ForgeTraining.recommend(s.profile),reasons=Array.isArray(rec.rationale)?rec.rationale:[rec.rationale],saved=s.profilePlanIds?s.routines.filter(r=>s.profilePlanIds.includes(r.id)):s.routines.filter(r=>/^(?:FORGE|GYM) \/ /.test(r.name));return `<section class="card plan-card"><div class="plan-summary"><span class="tag">YOUR PLAN</span><h2>${esc(rec.summary||'Your editable starter plan')}</h2><p>${esc(reasons[0]||'This plan is a starting point. Change any movement to suit yourself.')}</p><details class="plan-details"><summary>Why these movements?</summary><ul>${reasons.filter(Boolean).map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul><p>${esc(rec.loadHint)}</p><p>${esc(rec.progressionHint)}</p><p>${esc(rec.activityHint)}</p><p class="help">${esc(rec.notice)}</p></details></div><div class="plan-actions">${saved.slice(0,2).map(r=>`<button class="secondary" data-action="use-routine" data-id="${esc(r.id)}">Start ${esc(r.name.replace(/^(?:FORGE|GYM) \/ /,''))}</button>`).join('')||'<button class="secondary" data-page="routines">Browse starter plans</button>'}<button class="ghost" data-action="setup">Edit my choices</button></div></section>`}
function setup(step=0,reset=true){
 if(step===0&&reset){setupDraft={version:1,ageGroup:'40-64',weightKg:null,heightCm:null,goal:'fitness',experience:'beginner',days:3,minutes:30,equipment:['bodyweight'],impact:'standard',limitations:'',bodyFocus:'balanced',supersets:false,...state.profile};if(!Array.isArray(setupDraft.equipment))setupDraft.equipment=[setupDraft.equipment];}
 setupStep=step;
 const select=(id,label,options)=>`<label for="p-${id}">${label}</label><select id="p-${id}" name="${id}">${options.map(([value,labelText])=>`<option value="${value}" ${String(setupDraft[id])===String(value)?'selected':''}>${labelText}</option>`).join('')}</select>`;
 const equipmentChoices=[['bodyweight','Bodyweight / no equipment'],['bands','Resistance bands'],['dumbbells','Dumbbells'],['gym','Gym machines or cables']];
 const selectedEquipment=Array.isArray(setupDraft.equipment)?setupDraft.equipment:[setupDraft.equipment];
 const equipmentField=`<fieldset class="equipment-fieldset"><legend>What can you use? Choose all that apply.</legend><div class="equipment-options">${equipmentChoices.map(([value,label])=>`<label class="equipment-option"><input type="checkbox" name="equipment" value="${value}" ${selectedEquipment.includes(value)?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset>`;
 let body='';
 if(step===0)body=`<p class="subtle">Choose a simple starting point. You can edit any movement later; you do not need to enter your height or weight.</p><div class="setup-fields">${select('goal','What would you like to work on?',[['fitness','General fitness'],['strength','Get stronger'],['muscle','Build muscle'],['fatLoss','Support weight management'],['endurance','Build endurance']])}${select('experience','Where are you starting from?',[['beginner','I’m new'],['returning','Coming back after a break'],['experienced','I train often']])}${select('days','How many days are available?',[1,2,3,4,5,6,7].map(n=>[n,n+(n===1?' day':' days')]) )}${select('minutes','How much time per session?',[15,20,30,45,60,75,90].map(n=>[n,n+' minutes']))}</div>${equipmentField}<details class="plan-advanced"><summary>More ways to customize</summary><div class="setup-fields">${select('bodyFocus','Which area should get more attention?',[['balanced','Balanced'],['upper','Upper body'],['lower','Lower body'],['core','Core'],['push','Pushing movements'],['pull','Pulling movements']])}</div><label class="check-label" for="p-supersets"><input id="p-supersets" type="checkbox" name="supersets" ${setupDraft.supersets?'checked':''}> Pair accessory moves into supersets <span class="help-inline">Do one set of each paired move before resting. Optional.</span></label></details><p class="help">A plan is only a suggestion. Forge does not choose a weight from your body size.</p>`;
 else if(step===1){const ages=[['under18','Under 18'],['18-39','18–39'],['40-64','40–64'],['65-74','65–74'],['75+','75 or older']];if(setupDraft.ageGroup==='adult')ages.push(['adult','18–64 · existing profile']);if(setupDraft.ageGroup==='older')ages.push(['older','65+ · existing profile']);body=`<p class="subtle">Choose the age range that fits. This helps Forge set cautious plan defaults; it is not a health assessment.</p><div class="setup-fields">${select('ageGroup','Age range',ages)}${select('impact','Movement style', [['standard','Regular movement'],['low','Lower impact or gentle options']])}</div><label for="p-limitations">Anything the plan should avoid? <span class="help-inline">Optional</span></label><textarea name="limitations" id="p-limitations" maxlength="500" placeholder="Leave blank if you have no movement restrictions.">${esc(setupDraft.limitations)}</textarea><p class="help">This optional note stays with your training profile. If you use account sync, it is sent to the app owner; do not enter private medical details. A movement limitation pauses automatic plan suggestions so you can seek guidance first. Under 18, you can log workouts, but Forge will not create an automatic plan.</p>`;}
 else{let rec;try{setupDraft=ForgeTraining.validateProfile(setupDraft);rec=ForgeTraining.recommend(setupDraft)}catch(err){toast(err.message);return setup(1)}reviewedSessions=structuredClone(rec.sessions);body=`<p class="subtle">${esc(rec.summary)}</p><details class="plan-explanation"><summary>Why this plan?</summary><p>${esc(Array.isArray(rec.rationale)?rec.rationale.join(' '):rec.rationale)}</p><p>${esc(rec.loadHint)}</p><p>${esc(rec.progressionHint)}</p><p>${esc(rec.activityHint)}</p></details>${rec.sessions.map((routine,ri)=>`<section class="plan-preview"><label for="review-name-${ri}">Plan name</label><input id="review-name-${ri}" data-plan-name="${ri}" maxlength="180" value="${esc(routine.name)}">${routine.exercises.map((exercise,ei)=>`<div class="review-exercise"><label class="review-check"><input type="checkbox" data-plan-keep="${ri}:${ei}" checked> ${esc(exercise.name)}${exercise.sg?` <span class="tag">Superset ${esc(exercise.sg)}</span>`:''}</label>${guideButton(exercise)}<label>Sets<input data-plan-sets="${ri}:${ei}" type="number" min="1" max="10" required value="${exercise.sets.length}"></label><label>Reps<input data-plan-reps="${ri}:${ei}" type="number" min="1" max="100" required value="${exercise.sets[0]?.reps||10}"></label></div>`).join('')}</section>`).join('')}<div class="notice"><strong>Start comfortably</strong><br>${esc(rec.notice)}</div><p class="help plan-review-help">A set is one round of an exercise. Reps are how many times you repeat it.</p><p class="help">Your plan stays editable. Remove or replace a movement that does not suit you.</p>`;}
 modal('Build a plan that fits you',`<div class="setup-progress" role="progressbar" aria-label="Step ${step+1} of 3" aria-valuemin="1" aria-valuemax="3" aria-valuenow="${step+1}"><span class="${step===0?'current':''}">1 / Your routine</span><span class="${step===1?'current':''}">2 / Your needs</span><span class="${step===2?'current':''}">3 / Review</span></div><form id="setup-form">${body}<p id="setup-error" class="error" role="alert"></p><div class="button-row section-space wizard-actions">${step?'<button type="button" class="ghost" id="setup-back">Back</button>':''}<button type="submit">${step===2?(ForgeTraining.recommend(setupDraft).eligible?'Add my plan':'Save choices and continue'):'Continue'}</button><button type="button" class="ghost" id="setup-skip">Skip planning</button></div></form>`);
 $('#setup-skip').onclick=()=>{localStorage.setItem('forge-setup-skipped','1');setupDraft=null;$('#modal').close()};
 if(step)$('#setup-back').onclick=()=>setup(step-1,false);
 $('#setup-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);for(const [key,value] of form){if(key==='equipment'||key==='supersets')continue;setupDraft[key]=['days','minutes'].includes(key)?Number(value):['weightKg','heightCm'].includes(key)?(value===''?null:Number(value)):value;}if(step===0){setupDraft.equipment=form.getAll('equipment');setupDraft.supersets=form.has('supersets');if(!setupDraft.equipment.length){$('#setup-error').textContent='Choose at least one equipment option.';return;}}if(step<2){try{setupDraft=ForgeTraining.validateProfile(setupDraft);setup(step+1)}catch(err){$('#setup-error').textContent=err.message}return;}const rec=ForgeTraining.recommend(setupDraft);const sessions=reviewedSessions.map((routine,ri)=>{const exercises=routine.exercises.filter((exercise,ei)=>$(`[data-plan-keep="${ri}:${ei}"]`).checked).map((exercise,ei)=>{const originalIndex=routine.exercises.indexOf(exercise),count=Number($(`[data-plan-sets="${ri}:${originalIndex}"]`).value),reps=Number($(`[data-plan-reps="${ri}:${originalIndex}"]`).value);return {...exercise,sets:Array.from({length:count},()=>({...exercise.sets[0],reps,done:false}))};});ForgeSupersetOrder.normalizePairs(exercises);return {...routine,name:$(`[data-plan-name="${ri}"]`).value.trim()||routine.name,exercises};}).filter(routine=>routine.exercises.length);if(rec.eligible&&!sessions.length){$('#setup-error').textContent='Keep at least one exercise in your plan.';return;}const added=sessions.map(routine=>({id:uid(),name:'FORGE / '+routine.name,exercises:routine.exercises.map(exercise=>({...exercise,id:String(exercise.id||uid()),notes:exercise.notes||'',sets:exercise.sets.map(set=>({reps:set.reps,weight:set.weight||0,rpe:set.rpe??null,done:false}))}))}));if(state.routines.length+added.length>1000){$('#setup-error').textContent='Routine limit reached. Remove unused routines first.';return;}state.profile=structuredClone(setupDraft);state.profilePlanIds=added.map(routine=>routine.id);state.routines.push(...added);save();setupDraft=null;$('#modal').close();render();toast(added.length?'Profile saved. Your editable plan is in Plans.':'Profile saved. You can continue logging your own training.');};
}

function setLimit(field){return field==='rpe'?10:field==='seconds'?86400:field==='distanceKm'?1000:10000}
